    pinyin:'小{xiǎo}时{shí}不{bù}识{shí}月{yuè}，呼{hū}作{zuò}白{bái}玉{yù}盘{pán}。\n又{yòu}疑{yí}瑶{yáo}台{tái}镜{jìng}，飞{fēi}在{zài}青{qīng}云{yún}端{duān}。',
