    pinyin:'一道残阳铺{pū}水中，半江瑟{sè}瑟半江红。\n可怜九月初三夜，露似真珠月似弓。',
    translation:'一道残阳铺在水面上，江水一半呈现碧绿色，一半呈现红色。最可爱的是九月初三的夜晚，露珠像珍珠一样晶莹，月亮像弯弓一样。',
    analysis:'前两句写夕阳映江的绚丽色彩，「铺」字写出残阳贴水的柔和；后两句写新月夜景，用「真珠」「弓」两个比喻写露珠和月亮，清新可爱。',
    points:['「铺」读 pū，意为铺展','「瑟瑟」形容碧绿色','比喻：露珠—珍珠，月—弓']
