    pinyin:'葡萄美酒夜光杯，欲饮琵{pí}琶{pá}马上催。\n醉卧沙场君莫笑，古来征战几人回？',
    translation:'精美的酒杯里盛满葡萄美酒，正想畅饮，马上弹起的琵琶声却催人出征。即使醉倒在战场上您也不要笑话，自古以来出征打仗的人有几个能活着回来？',
    analysis:'前两句写边塞军中宴饮的豪迈场景；后两句以「醉卧沙场」的旷达和「几人回」的悲凉作结，豪放中见悲壮，写出将士视死如归的气概。',
    points:['「琵琶」读 pí pá','「沙场」指战场','情感：豪放中见悲壮']
