    pinyin:'生当作人杰，死亦为鬼雄。\n至今思项羽，不肯过江东。',
    translation:'活着就要做人中的豪杰，死了也要成为鬼中的英雄。时至今日人们还思念项羽，因为他兵败后不肯苟且偷生，逃回江东。',
    analysis:'这是一首借古讽今的咏史诗。诗人借项羽乌江自刎的典故，赞颂宁死不屈的气节，讽刺南宋朝廷的懦弱苟安。语言铿锵有力，气势豪迈。',
