    pinyin:'千里黄云白日曛{xūn}，北风吹雁雪纷纷。\n莫愁前路无知己，天下谁人不识君？',
    translation:'千里黄云遮天蔽日，太阳黯淡无光；北风吹着大雁，大雪纷纷飘落。不要担心前方的路上没有知己，天下有谁不认识你呢？',
    analysis:'前两句写送别时的恶劣环境，渲染离愁；后两句笔锋一转，以豪迈的语调安慰友人，表达对友人才华的肯定和真挚的情谊，成为送别诗中的名句。',
