    pinyin:'故人西辞黄鹤楼，烟花三月下扬州。\n孤帆远影碧空尽，唯见长江天际流。',
    translation:'老朋友在黄鹤楼与我告别，在繁花似锦的三月顺流东下扬州。孤帆的影子渐渐消失在碧空尽头，只看见长江浩浩荡荡地流向天边。',
    analysis:'前两句叙事点题，写出送别的时间、地点和去向；后两句写景，以「孤帆远影」「长江天际流」的辽阔画面，寄托对友人的依依惜别之情，含蓄而深远。',
