    pinyin:'渭{wèi}城朝{zhāo}雨浥{yì}轻尘，客舍青青柳色新。\n劝君更尽一杯酒，西出阳关无故人。',
    translation:'渭城清晨的细雨润湿了地上的轻尘，客舍旁的柳树显得格外青翠。劝您再喝一杯酒吧，向西出了阳关，就再也没有老朋友了。',
