    pinyin:'故人具鸡黍{shǔ}，邀我至田家。\n绿树村边合，青山郭外斜{xié}。\n开轩面场圃{pǔ}，把酒话桑麻。\n待到重阳日，还来就菊花。',
    translation:'老朋友准备了饭菜，邀请我到他的农家做客。绿树环绕着村庄，青山在城外横斜。打开窗户面对谷场菜园，举起酒杯谈论农事。等到重阳节那天，还要再来赏菊花。',
    analysis:'全诗写诗人到农家做客的情景，语言质朴自然。「绿树村边合，青山郭外斜」写景如画；「把酒话桑麻」写人情之淳朴。结尾约定再来，情谊深厚。',
