    pinyin:'春城无处不飞花，寒食东风御{yù}柳斜{xié}。\n日暮汉宫传蜡烛，轻烟散入五侯家。',
    translation:'暮春时节，长安城处处飞花，寒食节的东风吹得皇宫的柳枝倾斜。傍晚时分，宫中传出蜡烛，轻烟飘散到权贵人家。',
    analysis:'前两句写寒食节长安城的明媚春景；后两句写宫中赐烛的习俗。表面写节日景象，实则暗含对权贵得宠的讽刺，含蓄而不露。',
    points:['「寒食」是古代节日，禁烟火','「御柳」指皇宫中的柳树','「五侯」泛指权贵']
