    pinyin:'应{yīng}怜屐{jī}齿印苍苔，小扣柴扉{fēi}久不开。\n春色满园关不住，一枝红杏出墙来。',
    translation:'大概是园主人爱惜青苔，怕我的木屐踩坏它吧；我轻轻敲着柴门，久久没有人来开。可是满园的春色是关不住的，一枝红杏已经探出墙头来了。',
    analysis:'前两句写访友不遇的遗憾；后两句写意外的惊喜——「春色满园关不住，一枝红杏出墙来」，以少总多，由一枝红杏想到满园春色，成为千古名句。',
    points:['「应」读 yīng，意为大概','「屐」读 jī，指木底鞋','「值」意为遇到','名句：一枝红杏出墙来']
