    id:'p097', title:'登幽州台歌', dynasty:'唐', author:'陈子昂', level:'middle', grade:'七年级下', tag:'怀古',
    pinyin:'前不见古人，后不见来者。\n念天地之悠悠，独怆{chuàng}然而涕下！',
    translation:'往前看，见不到古代圣贤；往后看，也见不到后世明君。想到天地这样辽阔悠远，我独自悲伤落泪！',
    analysis:'诗人登台远眺，俯仰古今，感叹自己生不逢时、怀才不遇。前两句写时间的久远，第三句写空间的辽阔，最后以「独怆然而涕下」直抒胸臆，苍凉悲壮。',
    points:['「悠悠」形容时间久远、空间辽阔','「怆然」读 chuàng rán，悲伤的样子','「涕」指眼泪']
