    pinyin:'飞来山上千寻塔，闻说鸡鸣见日升。\n不畏浮云遮望眼，自缘身在最高层。',
    translation:'飞来峰上有一座高耸入云的塔，听说鸡鸣时就能看到太阳升起。不怕浮云遮住远望的视线，只因为自己站在最高层。',
